import{_ as p,a0 as a,w as s,s as u,ao as o,I as e,x as l,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"我如何通过开源来发展我的产品经理职业 | LCTT x X-CMD","titleTemplate":false,"description":"我如何通过开源来发展我的产品经理职业 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我如何通过开源来发展我的产品经理职业 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我如何通过开源来发展我的产品经理职业 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220427 How I grew my product management career with open source","title":"我如何通过开源来发展我的产品经理职业","tag":"202205","desc":""},"relativePath":"202205/20220427 How I grew my product management career with open source.md","filePath":"[post].md"}'),d={name:"202205/20220427 How I grew my product management career with open source.md"};function m(f,t,T,g,b,x){const r=a("Link");return s(),u("div",null,[t[29]||(t[29]=o('<h1 id="我如何通过开源来发展我的产品经理职业" tabindex="-1">我如何通过开源来发展我的产品经理职业 <a class="header-anchor" href="#我如何通过开源来发展我的产品经理职业" aria-label="Permalink to “我如何通过开源来发展我的产品经理职业”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/08/112446zy420r4zutdlu0ol.jpg" alt=""></p><blockquote><p>毫不夸张地说，在开源方面获得的经验，帮助我在产品管理领域创造了一条成功的职业道路。</p></blockquote><p>我是一个充满好奇心的人，我喜欢探索科技行业的许多领域，从视觉设计、编程到产品管理。我也被开放源码的理念所吸引。因此，我很高兴与大家分享我作为一个产品经理（PM），是如何利用开源来建立我的职业生涯的。我相信我的经验可以帮助其他对产品管理感兴趣的人。</p><h3 id="什么是开源软件" tabindex="-1">什么是开源软件 <a class="header-anchor" href="#什么是开源软件" aria-label="Permalink to “什么是开源软件”">​</a></h3>',5)),e("p",null,[t[1]||(t[1]=l("简单地说，开源软件是开放源代码的软件，这意味着任何人都可以检查、修改、增强和分享它的源代码。我们发表过一篇详细、",-1)),i(r,{href:"https://linux.cn/article-8624-1.html"},{default:n(()=>[...t[0]||(t[0]=[l("全面的文章",-1)])]),_:1}),t[2]||(t[2]=l(" 来帮助你了解什么是开源。",-1))]),t[30]||(t[30]=o('<p>我最早知道开源是很久以前了，那时，我还是一名刚入行不久的视觉设计师。我很想知道开源是什么，也很想知道如何成为它的一部分。在这种好奇心的驱使下，我接触到了一些有经验的开源贡献者和倡导者。虽然我当时没有做出贡献，但是他们让我知道了什么是社区，这对我下定决心开始贡献有很大帮助。</p><h3 id="如何上手产品管理" tabindex="-1">如何上手产品管理 <a class="header-anchor" href="#如何上手产品管理" aria-label="Permalink to “如何上手产品管理”">​</a></h3><p>产品管理工作貌似是一件很难上手的事情，感觉必须要戴上拳击手套，经过一番搏斗，才能强行进入这一行。然而，我从其他产品经理那里听说，与编写/调试代码块，或使用像素点生成复杂的产品设计线框相比，产品管理工作其实是更好上手的。</p><p>虽然我们的经历和经验各不相同，但是有一点可以确定：成为产品经理的道路往往是漫长而不可预知的。随着就业竞争的不断加剧，获得一个初级产品经理的职位可能会很困难。应聘者通常被要求有 2 到 3 年的经验才能加入产品团队。这时你可能会问：“我应该如何获得这些经验呢？”</p><p>来看看下面这四个策略吧，它们或许能够将你的职业生涯转向到产品管理：</p><ol><li>在一个大型组织的内部转岗。这可能需要你的经理为你说一些好话，比如，说你很适合在公司内部转岗等。你必须有证据表明你掌握了该岗位的技能。这通常被认为是获得产品管理经验的最快</li><li>担任大型组织的初级产品经理角色。通过它获得实习机会，或者加入一个需要初级产品经理的关副产品管理项目，这些都很常见。</li><li>你也可以尝试通过加入创业公司来上手产品管理工作。</li><li>你还可以启动一个自己的副业项目来上手产品管理工作。</li></ol>',6)),e("p",null,[t[4]||(t[4]=l("缺乏实践经验，就很难成为产品经理。正如开源产品经理 ",-1)),i(r,{href:"https://twitter.com/hellodavidryan"},{default:n(()=>[...t[3]||(t[3]=[l("David Ryan",-1)])]),_:1}),t[5]||(t[5]=l(" 所说，“有一条获得实际的产品管理经验的途径，它既未被人充分利用，也很少有人意识到并利用它们”。",-1))]),t[31]||(t[31]=e("p",null,"这条途径是什么？",-1)),t[32]||(t[32]=e("h3",{id:"答案就是开源",tabindex:"-1"},[l("答案就是开源 "),e("a",{class:"header-anchor",href:"#答案就是开源","aria-label":"Permalink to “答案就是开源”"},"​")],-1)),t[33]||(t[33]=e("p",null,"一个开放源码项目要想成功，需要的不仅仅是代码。它还包括项目战略、用户研究，以及将战略与日常工作联系起来。这些都是产品经理应该积极参加的活动。但是，在产品管理这一行里，有多少职责会分配给一个新手产品经理呢？",-1)),e("p",null,[i(r,{href:"https://twitter.com/susanavlopes"},{default:n(()=>[...t[6]||(t[6]=[l("Susana Videira Lopes",-1)])]),_:1}),t[7]||(t[7]=l(" 在她的一篇文章中指出，“获得一个入门级的产品角色，本质就是以一种建立你的信心的方式，让你加入到至产品管理这一行，同时尽早为组织提供价值”。",-1))]),t[34]||(t[34]=o('<p>一个入门级的产品经理该如何参与开源项目，并为它提供价值呢？</p><p><strong>答案很简单：多问问题</strong></p><p>这里有一些你可以问的问题：</p><ul><li>正在探索的是什么问题/机会？</li><li>如何制定解决方案来解决这个问题？</li><li>用什么标准来确定项目是否成功？</li><li>这个解决方案的服务对象是谁？</li><li>他们是如何被告知这个解决方案的？</li><li>该解决方案如何与当前和更广泛的生态系统相适应？</li><li>项目的文件是在哪里维护的？</li><li>项目维护者是否了解<ruby>无障碍<rt>accessibility</rt></ruby>要求？它们是否被满足？</li></ul><p>既然你已经获得了产品经理的所需技能，为何不应用它们呢？结合所学，表达出你深思熟虑的问题，并邀请你的团队来评估吧！你的团队可以选择那些能引起开发者和社区共鸣的问题，并优先考虑其中最重要的。</p><p>这些问题可以帮助你建立用户角色、用户旅程图、精益画布，以及更多。这种经验对发展职业潜力有很大的帮助。</p><h3 id="我在-openunited-的经历" tabindex="-1">我在 OpenUnited 的经历 <a class="header-anchor" href="#我在-openunited-的经历" aria-label="Permalink to “我在 OpenUnited 的经历”">​</a></h3>',7)),e("p",null,[i(r,{href:"https://openunited.com"},{default:n(()=>[...t[8]||(t[8]=[l("OpenUnited",-1)])]),_:1}),t[9]||(t[9]=l(" 是一个以独特方式连接数字人才和工作的平台。我们与贡献者合作，帮助他们投入到高质量的开源产品，从而证明自身的特定技能。一旦他们的工作得到验证，这些有才华的贡献者就有资格在公司里从事有偿工作。",-1))]),t[35]||(t[35]=o('<p>OpenUnited 是一个开源平台，为各类贡献者（包括产品经理、开发人员、设计师、商业分析师和其他人）提供服务。它致力于帮助贡献者提高技能，并为他们提供长期的高质量付费工作来源。</p><p>Miro 公司的高级产品经理 Farbod Saraf 让我加入他与合作伙伴创建的一个平台。我加入了这个项目，并了解了如何对 OpenUnited 做出贡献。我还了解了其他可以帮助我在产品管理生涯中成长的项目，并做出了我的第一次贡献。这是一次很好的经历，因为我可以迅速地开始投入到产品的某些部分，以改善平台上其他用户的体验。在我为项目做贡献的时候，我的导师 Farbod 随时为我提供任何需要的帮助，使我的工作更加轻松。</p><p>你对开源项目所做的一切贡献，都会成为你成长为产品经理过程中的有力的公共记录。对于任何想通过开源上手产品管理的人，我都强烈推荐 OpenUnited 平台。</p><h3 id="如何找到开源项目" tabindex="-1">如何找到开源项目 <a class="header-anchor" href="#如何找到开源项目" aria-label="Permalink to “如何找到开源项目”">​</a></h3><p>许多人认为，贡献开源只适合于开发人员，因为他们觉得找到一个可以舒适地贡献的开源项目是很难的。</p><p>即使作为一个初出茅庐的产品经理，也有好几种方法可以找到适合贡献的开源项目。这里列出了一些：</p><ul><li>在产品经理社区中发言，如 Mind The Product 和 Product School。</li><li>参加当地的聚会和开源会议，如非洲开源社区节，以此来与开源项目的创建者和维护者保持联系。</li><li>与在 GitLab 或 Mozilla 等大型开源公司工作的产品经理接触。他们可能会把你推荐到需要你的技能和贡献的开源项目中。</li><li>联系开源公司的开源倡导者和开发者关系团队，让他们推荐一些适合入门级产品经理贡献的开源项目。</li><li>寻找 AngelList 上的开源公司或 Product Hunt 上流行的开源产品。这些都是你可以找到适合贡献的开源产品的好地方。</li></ul><h3 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h3>',8)),e("p",null,[i(r,{href:"https://stars.github.com/profiles/ruth-ikegah/"},{default:n(()=>[...t[10]||(t[10]=[l("Ruth Ikegah",-1)])]),_:1}),t[12]||(t[12]=l(" 是我的一个重要灵感来源，她 ",-1)),i(r,{href:"https://ruthikegah.xyz/a-beginners-guide-to-open-source"},{default:n(()=>[...t[11]||(t[11]=[l("为开源新手写了一篇文章",-1)])]),_:1}),t[13]||(t[13]=l("。她的文章给出了一些提示，在你开始为开源做贡献时，可能需要考虑一下它们。",-1))]),t[36]||(t[36]=e("p",null,"在加入和贡献项目、社区或组织之前，对它们做一些研究，并提出自己的问题。当你最终决定加入社区时，试着积极地介绍自己，并说明你可以在哪些方面提供帮助。",-1)),t[37]||(t[37]=e("p",null,"当然，开源不仅仅是你职业生涯的一个垫脚石。它本身就是一个平台，而且它需要优秀的产品经理。参与进来吧！一方面，你能为社区做出贡献；另一方面，它也能帮助你磨练自己的技能。",-1)),t[38]||(t[38]=e("hr",null,null,-1)),e("p",null,[t[15]||(t[15]=l("via: ",-1)),i(r,{href:"https://opensource.com/article/22/4/product-management-open-source"},{default:n(()=>[...t[14]||(t[14]=[l("https://opensource.com/article/22/4/product-management-open-source",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=l("作者：",-1)),i(r,{href:"https://opensource.com/users/shebuel"},{default:n(()=>[...t[16]||(t[16]=[l("Shebuel Inyang",-1)])]),_:1}),t[21]||(t[21]=l(" 选题：",-1)),i(r,{href:"https://github.com/lkxed"},{default:n(()=>[...t[17]||(t[17]=[l("lkxed",-1)])]),_:1}),t[22]||(t[22]=l(" 译者：",-1)),i(r,{href:"https://github.com/lkxed"},{default:n(()=>[...t[18]||(t[18]=[l("lkxed",-1)])]),_:1}),t[23]||(t[23]=l(" 校对：",-1)),i(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[19]||(t[19]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=l("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[24]||(t[24]=[l("LCTT",-1)])]),_:1}),t[27]||(t[27]=l(" 原创编译，",-1)),i(r,{href:"https://linux.cn/"},{default:n(()=>[...t[25]||(t[25]=[l("Linux中国",-1)])]),_:1}),t[28]||(t[28]=l(" 荣誉推出",-1))])])}const w=p(d,[["render",m]]);export{k as __pageData,w as default};
